import { ApplicationConfig } from '@angular/core';
import { provideRouter, UrlSerializer, withHashLocation } from '@angular/router';
import { provideHttpClient } from '@angular/common/http';

import { routes } from './app.routes';
import { GwtUrlSerializer } from './gwt-url-serializer';

/**
 * Application configuration: hash-based routing on the GWT history tokens
 * (`#manufacturer`, `#rating`, `#report`) and the HTTP client used to call the
 * REST API at `/api` (same origin).
 */
export const appConfig: ApplicationConfig = {
    providers: [
        provideRouter(routes, withHashLocation()),
        // Serialize router URLs like GWT history tokens (#manufacturer, not
        // #/manufacturer) so the app keeps the GWT app's URL shape.
        { provide: UrlSerializer, useClass: GwtUrlSerializer },
        provideHttpClient(),
    ],
};
