import { Injectable, inject } from '@angular/core';
import { HttpErrorResponse, HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

import { ApiPaths, CarsResourceDefaults } from './api-paths';
import { CarDto, ManufacturerDto, ManufacturerRatingDto, RatingDto } from './dto';

/**
 * The REST client of the migrated application. It talks to the unchanged REST API
 * of the GWT backend (same origin, `/api`), one method per JAX-RS operation used
 * by the migrated screens (`ManufacturersResource`, `RatingResource`,
 * `CarsResource` and `SessionResource`).
 */
@Injectable({
    providedIn: 'root',
})
export class ApiService {
    private readonly http = inject(HttpClient);

    /** `GET /api/manufacturers` — `ManufacturersResource#getManufacturers`. */
    getManufacturers(): Observable<ManufacturerDto[]> {
        return this.http.get<ManufacturerDto[]>(ApiPaths.manufacturers());
    }

    /** `POST /api/manufacturers` — `ManufacturersResource#saveOrCreate`. */
    saveManufacturer(manufacturer: ManufacturerDto): Observable<ManufacturerDto> {
        return this.http.post<ManufacturerDto>(ApiPaths.manufacturers(), manufacturer);
    }

    /** `DELETE /api/manufacturers/{id}` — `ManufacturersResource#delete`. */
    deleteManufacturer(id: number | null): Observable<void> {
        return this.http.delete<void>(`${ApiPaths.manufacturers()}/${id}`);
    }

    /** `GET /api/manufacturers/ratings` — `ManufacturersResource#getAverageRatings`. */
    getAverageRatings(): Observable<ManufacturerRatingDto[]> {
        return this.http.get<ManufacturerRatingDto[]>(ApiPaths.manufacturerRatings());
    }

    /** `GET /api/ratings` — `RatingResource#getRatings`. */
    getRatings(): Observable<RatingDto[]> {
        return this.http.get<RatingDto[]>(ApiPaths.ratings());
    }

    /** `POST /api/ratings` — `RatingResource#saveOrCreate`. */
    saveRating(rating: RatingDto): Observable<RatingDto> {
        return this.http.post<RatingDto>(ApiPaths.ratings(), rating);
    }

    /** `DELETE /api/ratings/{id}` — `RatingResource#delete`. */
    deleteRating(id: number | null): Observable<void> {
        return this.http.delete<void>(`${ApiPaths.ratings()}/${id}`);
    }

    /**
     * `GET /api/cars?offset=0&limit=-1` — `CarsResource#getCars` called by the GWT
     * `EditRatingPresenter` with `(null, 0, CarsResource.LIMIT_ALL)`.
     */
    getAllCars(): Observable<CarDto[]> {
        const params = `offset=${CarsResourceDefaults.DEFAULT_OFFSET}&limit=${CarsResourceDefaults.LIMIT_ALL}`;
        return this.http.get<CarDto[]>(`${ApiPaths.cars()}?${params}`);
    }

    /** `DELETE /api/session` — `SessionResource#logout`. */
    logout(): Observable<void> {
        return this.http.delete<void>(ApiPaths.session());
    }
}

/**
 * Builds the text of an error message, mirroring the GWT
 * `ErrorHandlerAsyncCallback` which reports the HTTP failure cause.
 */
export function httpErrorMessage(error: unknown): string {
    if (error instanceof HttpErrorResponse) {
        if (error.status === 0) {
            return 'Unable to reach the server. Please try again.';
        }

        return `HTTP ${error.status}: ${error.statusText || 'Error'}`;
    }

    return 'An unexpected error occurred.';
}
