/**
 * Mirrors `RatingDto#toString()`: `"<manufacturer name>/<car model>"`
 * (e.g. `Honda/Accord`). The rating table's `Car` column shows this label.
 *
 * When a car's manufacturer was deleted (the backend leaves the car behind),
 * the label falls back to `null/<model>` — the same value the Java string
 * concatenation would produce — so the `manufacturer/model` shape is kept.
 */
export function ratingLabel(rating: RatingDto): string {
    if (rating.car) {
        return `${rating.car.manufacturer?.name ?? 'null'}/${rating.car.model}`;
    }

    return '';
