import { Injectable, signal } from '@angular/core';

/**
 * Mirrors `com.gwtplatform.carstore.client.application.widget.message.MessageStyle`.
 */
export enum MessageStyle {
    SUCCESS,
    ERROR,
}

/**
 * Mirrors `com.gwtplatform.carstore.client.application.widget.message.MessageCloseDelay`.
 */
export enum MessageCloseDelay {
    NEVER = 0,
    DEFAULT = 5000,
}

/**
 * A message currently displayed by the messages widget.
 */
export interface AppMessage {
    id: number;
    text: string;
    style: MessageStyle;
    closeDelayMs: number;
}

/**
 * Mirrors the GWT `DisplayMessageEvent` / `MessagesPresenter` / `MessageWidget`
 * combo: screens publish messages here and the messages widget (rendered once in
 * the application shell) displays and auto-closes them.
 */
@Injectable({
    providedIn: 'root',
})
export class MessagesService {
    private nextId = 0;

    private readonly messageList = signal<AppMessage[]>([]);

    /** All messages currently on screen (older first). */
    readonly messages = this.messageList.asReadonly();

    /** Mirrors `new Message(text, style)` — closes after the default delay. */
    addMessage(text: string, style: MessageStyle, closeDelay: MessageCloseDelay = MessageCloseDelay.DEFAULT): void {
        const message: AppMessage = {
            id: this.nextId++,
            text,
            style,
            closeDelayMs: closeDelay,
        };

        this.messageList.update(messages => [...messages, message]);

        if (closeDelay !== MessageCloseDelay.NEVER) {
            // Mirrors MessageWidget's close timer.
            setTimeout(() => this.close(message.id), closeDelay);
        }
    }

    success(text: string): void {
        this.addMessage(text, MessageStyle.SUCCESS);
    }

    error(text: string): void {
        this.addMessage(text, MessageStyle.ERROR);
    }

    /** Mirrors `MessageWidget#close` (the `X` link). */
    close(id: number): void {
        this.messageList.update(messages => messages.filter(message => message.id !== id));
    }
}
