import { Injectable } from '@angular/core';
import { DefaultUrlSerializer, UrlSerializer, UrlTree } from '@angular/router';

/**
 * A URL serializer that writes route URLs the way the GWT application wrote its
 * history tokens: `#manufacturer` instead of Angular's default `#/manufacturer`.
 *
 * The application uses hash-based routing (see `app.config.ts`). This serializer
 * only changes how trees are turned into strings — the leading `/` of the
 * default serializer is dropped so links point to `#manufacturer`, `#rating`,
 * `#report`, ... exactly like the GWT `PlaceManager` did. Parsing still accepts
 * both forms (with or without the leading `/`).
 */
@Injectable()
export class GwtUrlSerializer extends UrlSerializer {
    private readonly delegate = new DefaultUrlSerializer();

    override parse(url: string): UrlTree {
        return this.delegate.parse(url);
    }

    override serialize(tree: UrlTree): string {
        const url = this.delegate.serialize(tree);

        return url.startsWith('/') ? url.substring(1) : url;
    }
}
