import { Component, EventEmitter, Input, Output, OnInit, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { ApiService, httpErrorMessage } from '../core/api.service';
import { MessagesService } from '../core/messages.service';
import { ManufacturerDto } from '../core/dto';

/**
 * Mirrors `EditManufacturerPresenter` / `EditManufacturerView`: the create/edit
 * manufacturer popup with a name field, Save and Close buttons.
 */
@Component({
    selector: 'app-edit-manufacturer',
    standalone: true,
    imports: [FormsModule],
    templateUrl: './edit-manufacturer.component.html',
})
export class EditManufacturerComponent implements OnInit {
    /**
     * The manufacturer being edited, or null to create a new one
     * (GWT: `edit(manufacturerDto)` / `createNew()`).
     */
    @Input()
    manufacturer: ManufacturerDto | null = null;

    /** Emits the manufacturer returned by the server after a successful save. */
    @Output()
    saved = new EventEmitter<ManufacturerDto>();

    /** Emits when the popup is closed (Close button or glass panel). */
    @Output()
    closed = new EventEmitter<void>();

    /** Mirrors the `name` TextBox of the GWT editor. */
    protected name = '';

    private readonly api = inject(ApiService);
    private readonly messages = inject(MessagesService);

    ngOnInit(): void {
        this.name = this.manufacturer?.name ?? '';
    }

    /** Mirrors `EditManufacturerPresenter#onSave`. */
    protected save(): void {
        const manufacturer: ManufacturerDto = {
            id: this.manufacturer?.id ?? null,
            name: this.name,
            cars: this.manufacturer?.cars ?? [],
        };

        this.api.saveManufacturer(manufacturer).subscribe({
            next: savedManufacturer => {
                this.messages.success('The manufacturer has been saved.');
                this.saved.emit(savedManufacturer);
                this.closed.emit();
            },
            error: error => this.messages.error(httpErrorMessage(error)),
        });
    }

    /** Mirrors `EditManufacturerPresenter#onCancel`. */
    protected close(): void {
        this.closed.emit();
    }
}
