import { Component, OnInit, inject } from '@angular/core';

import { ApiService, httpErrorMessage } from '../core/api.service';
import { MessagesService } from '../core/messages.service';
import { ManufacturerDto } from '../core/dto';
import { EditManufacturerComponent } from './edit-manufacturer.component';

/**
 * Mirrors `ManufacturerPresenter` / `ManufacturerView`: the manufacturers table
 * with a create button, an Edit and Delete action per row, and the create/edit
 * popup (`EditManufacturerView`).
 */
@Component({
    selector: 'app-manufacturers',
    standalone: true,
    imports: [EditManufacturerComponent],
    templateUrl: './manufacturers.component.html',
    styleUrl: './manufacturers.component.css',
})
export class ManufacturersComponent implements OnInit {
    private readonly api = inject(ApiService);
    private readonly messages = inject(MessagesService);

    /** The rows of the manufacturer table (`ListDataProvider`'s list in GWT). */
    protected manufacturers: ManufacturerDto[] = [];

    /** Mirrors `ManufacturerPresenter#editingManufacturer` — null when creating. */
    protected editingManufacturer: ManufacturerDto | null = null;

    /** Whether the create/edit popup is on screen. */
    protected editorVisible = false;

    ngOnInit(): void {
        this.loadManufacturers();
    }

    /** Mirrors `ManufacturerPresenter#onReveal` — (re)loads the table. */
    protected loadManufacturers(): void {
        this.api.getManufacturers().subscribe({
            next: manufacturers => (this.manufacturers = manufacturers),
            error: error => this.messages.error(httpErrorMessage(error)),
        });
    }

    /** Mirrors `onCreate` — opens the editor for a new manufacturer. */
    protected createManufacturer(): void {
        this.editingManufacturer = null;
        this.editorVisible = true;
    }

    /** Mirrors `onEdit` — opens the editor on an existing manufacturer. */
    protected editManufacturer(manufacturer: ManufacturerDto): void {
        this.editingManufacturer = manufacturer;
        this.editorVisible = true;
    }

    /**
     * Mirrors `onDelete` — asks for confirmation (`Window.confirm` in GWT) before
     * deleting the manufacturer.
     */
    protected deleteManufacturer(manufacturer: ManufacturerDto): void {
        const confirmed = window.confirm(
            `Are you sure you want to delete ${manufacturer.name}?`,
        );

        if (confirmed) {
            this.api.deleteManufacturer(manufacturer.id).subscribe({
                next: () => this.removeManufacturer(manufacturer),
                error: error => this.messages.error(httpErrorMessage(error)),
            });
        }
    }

    /** Mirrors the `ManufacturerAddedEvent` handler. */
    protected onManufacturerSaved(savedManufacturer: ManufacturerDto): void {
        if (this.editingManufacturer) {
            this.replaceManufacturer(this.editingManufacturer, savedManufacturer);
        } else {
            this.addManufacturer(savedManufacturer);
        }

        this.editingManufacturer = savedManufacturer;
        this.editorVisible = false;
    }

    protected onEditorClosed(): void {
        this.editorVisible = false;
    }

    private addManufacturer(manufacturer: ManufacturerDto): void {
        this.manufacturers.push(manufacturer);
    }

    private removeManufacturer(manufacturer: ManufacturerDto): void {
        this.manufacturers = this.manufacturers.filter(m => m.id !== manufacturer.id);
    }

    private replaceManufacturer(oldManufacturer: ManufacturerDto, newManufacturer: ManufacturerDto): void {
        const index = this.manufacturers.findIndex(m => m.id === oldManufacturer.id);

        if (index >= 0) {
            this.manufacturers[index] = newManufacturer;
        } else {
            this.manufacturers.push(newManufacturer);
        }
    }
}
