import { Component, EventEmitter, Output, OnInit, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { ApiService, httpErrorMessage } from '../core/api.service';
import { MessagesService } from '../core/messages.service';
import { CarDto, RatingDto } from '../core/dto';

/**
 * Mirrors `EditRatingPresenter` / `EditRatingView`: the create-rating popup with
 * a car picker, a rating field, Save and Close buttons.
 *
 * Like the GWT presenter, the allowed cars are loaded before the form is shown.
 */
@Component({
    selector: 'app-edit-rating',
    standalone: true,
    imports: [FormsModule],
    templateUrl: './edit-rating.component.html',
})
export class EditRatingComponent implements OnInit {
    /** Emits the rating returned by the server after a successful save. */
    @Output()
    saved = new EventEmitter<RatingDto>();

    /** Emits when the popup is closed (Close button or glass panel). */
    @Output()
    closed = new EventEmitter<void>();

    /** Mirrors the `car` ValueListBox's acceptable values. */
    protected cars: CarDto[] = [];

    /** Mirrors the `car` ValueListBox's value (first allowed car by default). */
    protected car: CarDto | null = null;

    /** Mirrors the `rating` IntegerBox (empty for a new rating). */
    protected ratingInput = '';

    /** Mirrors `EditRatingPresenter#reveal` showing the popup once cars are loaded. */
    protected formReady = false;

    private readonly api = inject(ApiService);
    private readonly messages = inject(MessagesService);

    ngOnInit(): void {
        this.api.getAllCars().subscribe({
            next: cars => {
                this.cars = cars;
                this.car = cars.length > 0 ? cars[0] : null;
                this.formReady = true;
            },
            error: error => {
                this.messages.error(httpErrorMessage(error));
                this.closed.emit();
            },
        });
    }

    /** Mirrors `EditRatingPresenter#onSave`. */
    protected save(): void {
        const rating: RatingDto = {
            id: null,
            rating: this.parseRating(),
            car: this.car,
        };

        this.api.saveRating(rating).subscribe({
            next: savedRating => {
                this.messages.success('The rating has been saved.');
                this.saved.emit(savedRating);
                this.closed.emit();
            },
            error: error => this.messages.error(httpErrorMessage(error)),
        });
    }

    /** Mirrors `EditRatingPresenter#onCancel`. */
    protected close(): void {
        this.closed.emit();
    }

    /** Mirrors the car renderer used by the ValueListBox. */
    protected carLabel(car: CarDto): string {
        return `${car.manufacturer?.name ?? 'null'}/${car.model}`;
    }

    /** Mirrors the IntegerBox's parsing of the entered value. */
    private parseRating(): number | null {
        const trimmed = this.ratingInput.trim();

        if (trimmed === '') {
            return null;
        }

        const parsed = Number(trimmed);

        return Number.isNaN(parsed) ? null : parsed;
    }
}
