import { Component, OnInit, inject } from '@angular/core';

import { ApiService, httpErrorMessage } from '../core/api.service';
import { MessagesService } from '../core/messages.service';
import { RatingDto, ratingLabel } from '../core/dto';
import { EditRatingComponent } from './edit-rating.component';

/**
 * Mirrors `RatingPresenter` / `RatingView`: the ratings table with a create
 * button and a Delete action per row, plus the create-rating popup
 * (`EditRatingView`).
 */
@Component({
    selector: 'app-ratings',
    standalone: true,
    imports: [EditRatingComponent],
    templateUrl: './ratings.component.html',
    styleUrl: './ratings.component.css',
})
export class RatingsComponent implements OnInit {
    private readonly api = inject(ApiService);
    private readonly messages = inject(MessagesService);

    /** The rows of the rating table (`ListDataProvider`'s list in GWT). */
    protected ratings: RatingDto[] = [];

    /** Whether the create-rating popup is on screen. */
    protected editorVisible = false;

    ngOnInit(): void {
        this.loadRatings();
    }

    /** Mirrors `RatingPresenter#onReveal` — (re)loads the table. */
    protected loadRatings(): void {
        this.api.getRatings().subscribe({
            next: ratings => (this.ratings = ratings),
            error: error => this.messages.error(httpErrorMessage(error)),
        });
    }

    /** Mirrors `onCreate` — opens the editor for a new rating. */
    protected createRating(): void {
        this.editorVisible = true;
    }

    /**
     * Mirrors `onDelete` — asks for confirmation (`Window.confirm` in GWT) before
     * deleting the rating.
     */
    protected deleteRating(rating: RatingDto): void {
        const confirmed = window.confirm(
            `Are you sure you want to delete${ratingLabel(rating)}?`,
        );

        if (confirmed) {
            this.api.deleteRating(rating.id).subscribe({
                next: () => this.removeRating(rating),
                error: error => this.messages.error(httpErrorMessage(error)),
            });
        }
    }

    /** Mirrors the `RatingAddedEvent` handler. */
    protected onRatingSaved(savedRating: RatingDto): void {
        this.ratings.push(savedRating);
        this.editorVisible = false;
    }

    protected onEditorClosed(): void {
        this.editorVisible = false;
    }

    /** The `Car` column renders `RatingDto#toString()`: `<manufacturer>/<model>`. */
    protected carLabel(rating: RatingDto): string {
        return ratingLabel(rating);
    }

    private removeRating(rating: RatingDto): void {
        this.ratings = this.ratings.filter(r => r.id !== rating.id);
    }
}
