    /** The GWT history token used as route path / `href`. */
    token: string;
    label: string;
}

/**
 * Mirrors `HeaderView` — the application header with the menubar used to move
 * between the screens. Links keep the GWT history tokens in their `href`
 * (`#manufacturer`, `#rating`, ...), so navigation still works through the
 * menubar like in the GWT application.
 */
@Component({
    selector: 'app-header',
    standalone: true,
    imports: [RouterLink, RouterLinkActive],
    templateUrl: './header.component.html',
    styleUrl: './header.component.css',
