export class HeaderComponent {
    private readonly api = inject(ApiService);
    private readonly router = inject(Router);
    private readonly messages = inject(MessagesService);

    protected readonly links: MenuLink[] = [
        { token: NameTokens.MANUFACTURER, label: 'Manufacturers' },
        { token: NameTokens.CARS, label: 'Cars' },
        { token: NameTokens.RATING, label: 'Ratings' },
        { token: NameTokens.REPORT, label: 'Reports' },
        { token: NameTokens.STATS, label: 'Statistics' },
    ];

    /** Mirrors `HeaderPresenter#logout` — `SessionResource#logout`. */
    protected logout(): void {
