import { Component, EventEmitter, Input, Output } from '@angular/core';

import { gwtDebugId } from '../../../debug-ids';
import { AppMessage, MessageStyle } from '../../../core/messages.service';

/**
 * Mirrors `MessageWidget` — one dismissible message box.
 *
 * The GWT widget assigned the `successMessage` / `errorMessage` debug ids to the
 * message box, so the migrated widget does the same (the end-to-end tests find
 * them through `ByDebugId`).
 */
@Component({
    selector: 'app-message',
    standalone: true,
    templateUrl: './message.component.html',
    styleUrl: './message.component.css',
})
export class MessageComponent {
    @Input({ required: true })
    message!: AppMessage;

    @Output()
    closed = new EventEmitter<number>();

    /** Exposes the style enum to the template. */
    protected readonly styles = MessageStyle;

    /** Mirrors `MessageWidget#initContent`: `ensureDebugId(messageBox, "successMessage" | "errorMessage")`. */
    protected get domId(): string {
        return gwtDebugId(
            this.message.style === MessageStyle.SUCCESS ? 'successMessage' : 'errorMessage',
        );
    }

    /** Mirrors the `X` link's click handler. */
    protected close(): void {
        this.closed.emit(this.message.id);
    }
}
